import axios from 'axios';
export default {
  data() {
    return {
      userInfo: [],
      changePasswordDialog: false,
      passwordForm: {
        old_password: '',
        new_password1: '',
        new_password2: ''
      },
      snackbar: false,
      snackbarMessage: ''
    };
  },
  mounted() {
    this.fetchUserDetails();
  },
  methods: {
    async fetchUserDetails() {
      try {
        const response = await axios.get('/users/api/profile/');
        this.userInfo = response.data.user_info;
      } catch (error) {
        console.error('Error fetching user details:', error);
      }
    },
    showChangePasswordDialog() {
      this.changePasswordDialog = true;
    },
    async changePassword() {
      try {
        await axios.post('/users/api/change-password/', this.passwordForm);
        this.changePasswordDialog = false;
        this.showSuccessMessage('Password changed successfully');
        this.passwordForm = {
          old_password: '',
          new_password1: '',
          new_password2: ''
        };
      } catch (error) {
        console.error('Error changing password:', error);
        this.showErrorMessage('Failed to change password. Please try again.');
      }
    },
    showSuccessMessage(message) {
      this.snackbarMessage = message;
      this.snackbar = true;
    },
    showErrorMessage(message) {
      this.snackbarMessage = message;
      this.snackbar = true;
    }
  }
};
